flowchart TB
  subgraph G5["5 複雑な処理"]
    SF@{ svc: "AWS Step Functions", label: "Lambda と<br/>Step Functions" }
  end
  subgraph G4["4 準拠を保つ"]
    CO@{ svc: "AWS Systems Manager", label: "Compliance<br/>準拠を一か所で" }
    REM@{ svc: "AWS Config", label: "AWS Config<br/>合わない物を直す" }
  end
  subgraph G3["3 あるべき状態"]
    SM@{ svc: "AWS Systems Manager", label: "State Manager<br/>似た機能と比べる" }
  end
  subgraph G2["2 パッチ"]
    PM@{ svc: "AWS Systems Manager", label: "Patch Manager<br/>方法と準拠" }
  end
  subgraph G1["1 棚卸しと構成"]
    INV@{ svc: "AWS Systems Manager", label: "Inventory<br/>ノードの情報" }
    CFG@{ svc: "AWS Config", label: "AWS Config<br/>構成と履歴" }
  end

flowchart TB
  PM@{ svc: "AWS Systems Manager", label: "Patch Manager<br/>パッチの準拠" }
  SM@{ svc: "AWS Systems Manager", label: "State Manager<br/>association の準拠" }
  CO@{ svc: "AWS Systems Manager", label: "Compliance<br/>今の準拠のデータ" }
  F["多くの管理対象のノード"]
  PM -- "既定で表示" --> CO
  SM -- "既定で表示" --> CO
  CO -- "スキャン" --> F

flowchart TB
  RULE@{ svc: "AWS Config", label: "AWS Config Rules<br/>リソースを評価" }
  NC["ルールに合わない<br/>リソース"]
  CFG@{ svc: "AWS Config", label: "AWS Config<br/>修復を適用" }
  AU@{ svc: "AWS Systems Manager", label: "Automation の<br/>ドキュメント" }
  API["aws:executeAwsApi<br/>AWS の API 操作を呼ぶ"]
  RULE -- "合わないと評価" --> NC
  CFG -- "使う" --> AU
  AU -- "修復する" --> NC
  AU -. "アクションの一つ" .-> API

flowchart TB
  subgraph G5["5 複雑な処理"]
    SF@{ svc: "AWS Step Functions", label: "Lambda の再試行<br/>Standard と Express" }
  end
  subgraph G4["4 準拠を保つ"]
    CO@{ svc: "AWS Systems Manager", label: "Compliance<br/>準拠を一か所で" }
    REM@{ svc: "AWS Config", label: "AWS Config<br/>Automation で修復" }
  end
  subgraph G3["3 あるべき状態"]
    SM@{ svc: "AWS Systems Manager", label: "State Manager<br/>association で保つ" }
  end
  subgraph G2["2 パッチ"]
    PM@{ svc: "AWS Systems Manager", label: "Patch Manager<br/>物差しは baseline" }
  end
  subgraph G1["1 棚卸しと構成"]
    INV@{ svc: "AWS Systems Manager", label: "Inventory<br/>S3 に集めて調べる" }
    CFG@{ svc: "AWS Config", label: "AWS Config<br/>関係と履歴" }
  end
